function scrollToY(t){window.scrollTo({top:t,behavior:"smooth"})}window.addEventListener("load",function(){let o=document.querySelector(".page-header"),n=document.querySelectorAll(".animation-up"),l=document.querySelectorAll(".animation-left"),a=document.querySelectorAll(".animation-right"),r=document.querySelectorAll(".animation-show"),e=(scrollToY(0),window.innerHeight);n.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateY(0)")}),l.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateX(0)")}),a.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateX(0)")}),r.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1")}),window.addEventListener("scroll",function(t){72<window.pageYOffset?o.classList.add("page-header__scroll"):o.classList.remove("page-header__scroll");let e=window.innerHeight;n.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateY(0)")}),l.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateX(0)")}),a.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1",t.style.transform="translateX(0)")}),r.forEach(t=>{t.getBoundingClientRect().top<e-10&&(t.style.opacity="1")})})});